import axios from "axios";
import { useEffect, useState } from "react";

const PostList = () => {
  const [posts, setPosts] = useState();
  const fetchData = async () => {
    return await axios.get("http://localhost:4000/posts");
  };

  useEffect();

  return (
    <div>
      <h1>List Post</h1>
      <ul></ul>
    </div>
  );
};

export default PostList;
